// Accuracy of the on-device bill reader on Adaption-generated Gujarat bills.
//
// The bills are synthetic OCR text across every DISCOM, with bilingual labels and OCR noise,
// generated by backend/tools/invent_bill_tests.py and verified against their own text there.
// They are test data only.
import { existsSync, readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { parseBillText } from "./billParser";

const FIXTURE = new URL("./__fixtures__/bills.adaption.jsonl", import.meta.url);

interface Case {
  text: string;
  units_kwh: number;
  billing_days: number | null;
  amount_rs: number | null;
}

function load(): Case[] {
  if (!existsSync(FIXTURE)) return [];
  return readFileSync(FIXTURE, "utf8")
    .split("\n")
    .filter((l) => l.trim())
    .map((l) => JSON.parse(l))
    .filter((r) => !("_source" in r));
}

const cases = load();
// Raise this as the parser improves; the test fails if accuracy drops below it.
const MIN_UNITS_ACCURACY = 0.85;

describe.skipIf(cases.length === 0)("bill reader on Adaption-generated bills", () => {
  it(`reads units correctly on at least ${MIN_UNITS_ACCURACY * 100}% of ${cases.length} bills`, () => {
    let units = 0;
    let days = 0;
    let daysTotal = 0;
    let amount = 0;
    let amountTotal = 0;
    const misses: string[] = [];
    for (const c of cases) {
      const parsed = parseBillText(c.text);
      if (parsed.unitsKwh === c.units_kwh) units++;
      else if (misses.length < 5) misses.push(`expected ${c.units_kwh}, got ${parsed.unitsKwh}:\n${c.text.slice(0, 400)}`);
      if (c.billing_days !== null) {
        daysTotal++;
        if (parsed.billingDays === c.billing_days) days++;
      }
      if (c.amount_rs !== null) {
        amountTotal++;
        if (parsed.amountRs === c.amount_rs) amount++;
      }
    }
    const pct = (n: number, d: number) => (d ? `${((n / d) * 100).toFixed(1)}%` : "n/a");
    console.log(
      `Bill reader on ${cases.length} Adaption bills: units ${pct(units, cases.length)}, ` +
        `billing days ${pct(days, daysTotal)}, amount ${pct(amount, amountTotal)}`,
    );
    if (misses.length) console.log(`First misses:\n${misses.join("\n---\n")}`);
    expect(units / cases.length).toBeGreaterThanOrEqual(MIN_UNITS_ACCURACY);
  });
});
